const valueScript = `<script>(()=>{const form=document.getElementById("value-form"),keyInput=document.getElementById("valueApiKey"),loadButton=document.getElementById("load-deliveries"),select=document.getElementById("processedLotRef"),buyer=document.getElementById("buyerRef"),feedback=document.getElementById("value-feedback"),list=document.getElementById("value-list"),submit=form.querySelector('button[type="submit"]');let apiKey="",records=[];const transfersFor=lotRef=>records.filter(record=>record.canonicalType==="custody-transfer"&&record.content?.lotRef===lotRef),refresh=()=>{buyer.value=select.selectedOptions[0]?.dataset.buyer??""};const render=()=>{const valued=new Set(records.filter(record=>record.canonicalType==="value-status"&&record.content?.processedLotRef).map(record=>record.content?.processedLotRef));select.replaceChildren(new Option("Select a delivered processed lot",""));for(const lot of records.filter(record=>record.canonicalType==="material-lot"&&record.content?.material==="processed-cocoa"&&record.content?.qualityStatus==="accepted"&&!valued.has(record.canonicalId))){const latest=transfersFor(lot.canonicalId).at(-1);if(!latest||latest.content?.toCustodianRef===lot.content?.custodianRef)continue;const option=new Option(String(lot.content?.fixtureId??lot.canonicalId),lot.canonicalId);option.dataset.buyer=String(latest.content?.toCustodianRef??"");select.append(option)}select.disabled=false;refresh();list.replaceChildren();const statuses=records.filter(record=>record.canonicalType==="value-status"&&record.content?.processedLotRef);if(!statuses.length)list.textContent="No cocoa Value statuses are present.";for(const record of statuses){const item=document.createElement("div"),name=document.createElement("strong"),detail=document.createElement("span");item.className="transfer";name.textContent=String(record.content?.processedLotRef??record.canonicalId);detail.textContent=String(record.content?.realizationStatus??record.assertionStatus)+" · "+String(record.content?.considerationStatus??"?");item.append(name,detail);list.append(item)}};const load=async()=>{const response=await fetch("/v2/records",{headers:{authorization:"Bearer "+apiKey}});if(!response.ok)throw new Error("Could not load delivered processed lots");records=(await response.json()).records;render()};loadButton.addEventListener("click",async()=>{loadButton.disabled=true;feedback.textContent="Loading delivered processed lots…";try{apiKey=keyInput.value;await load();feedback.textContent="Delivered lots and Value statuses loaded."}catch(error){feedback.textContent=error instanceof Error?error.message:"Loading failed"}finally{loadButton.disabled=false}});select.addEventListener("change",refresh);form.addEventListener("submit",async event=>{event.preventDefault();submit.disabled=true;feedback.textContent="Recording Value status…";try{apiKey=keyInput.value||apiKey;const data=new FormData(form),value=name=>String(data.get(name)??"").trim(),realizationId=value("realizationId"),envelope={commandId:"operator-"+realizationId,agentRef:value("agentRef"),agencyRef:value("agencyRef"),authorityRef:value("authorityRef"),purposeRef:value("purposeRef"),evidenceRefs:[value("evidenceRef")],attributionRule:value("attributionRule"),command:{commandType:"recordCocoaDeliveryValue",payload:{realizationId,processedLotRef:value("processedLotRef"),buyerRef:value("buyerRef"),purposeFulfilled:value("purposeFulfilled")==="true",considerationStatus:value("considerationStatus")}}};const response=await fetch("/v2/commands",{method:"POST",headers:{authorization:"Bearer "+apiKey,"content-type":"application/json","idempotency-key":envelope.commandId},body:JSON.stringify(envelope)}),body=await response.json();if(!response.ok)throw new Error(body.error?.message??"Value recording failed");keyInput.value="";await load();feedback.textContent="Delivery Outcome and evidence-backed Value status persisted atomically."}catch(error){feedback.textContent=error instanceof Error?error.message:"Value recording failed"}finally{submit.disabled=false}})})();</script>`;
const pageContent = (route: OperatorRoute): string => route.path === "/lots" ? cocoaLotsContent : route.path === "/transfers" ? custodyTransferContent : route.path === "/workflow" ? processingContent + completionContent + processedLotContent + valueContent : cards(route);

export const renderOperatorPage = (pathname: string): OperatorPage | undefined => {
  const route = operatorRoutes.find((candidate) => candidate.path === pathname);
  if (!route) return undefined;
  const script = route.path === "/lots" ? cocoaLotsScript : route.path === "/transfers" ? custodyTransferScript : route.path === "/workflow" ? processingScript + completionScript + processedLotScript + valueScript : "";
  return { statusCode: 200, contentType: "text/html; charset=utf-8", body: `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="OriginOS cocoa operations workspace"><title>${route.title} · OriginOS</title><style>${styles}${lotStyles}${transferStyles}</style></head><body><a class="skip" href="#content">Skip to content</a><div class="layout"><aside class="sidebar"><div class="brand"><span class="mark" aria-hidden="true">O</span>originOS</div><nav class="nav" aria-label="Operator navigation">${navigation(route.path)}</nav><div class="release">SW2 bounded-alpha RC1<br>Release 0.17.0-rc.1</div></aside><main class="main" id="content"><header class="topbar"><div class="environment"><span class="dot" aria-hidden="true"></span>Operator workspace</div><div class="avatar" aria-label="Merchant operator">MO</div></header><div class="hero"><p class="eyebrow">${route.eyebrow}</p><h1>${route.title}</h1><p class="summary">${route.summary}</p></div>${pageContent(route)}</main></div>${script}</body></html>` };
};
export const operatorWebApp = Object.freeze({ render: renderOperatorPage });
